def main():
 stage=RESULTS/'exploratory-epoch2-v4';out=PARENT/'exploratory-epoch2-v4';summary=json.loads((stage/'summary.json').read_text(encoding='utf-8'));assert summary['allDevelopmentTextIntervalPaddingAcceptEqual'] and summary['priorSelectedTorchRawReproducedExactly'];q=json.loads((RESULTS/'qualification.json').read_text(encoding='utf-8'));assert q['originalTrial'].startswith('FAIL') and q['activeBaselineFallback'];selection=json.loads((ROOT/'selection.json').read_text(encoding='utf-8'));c=selection['selected'];assert c['epoch']==2 and sha(c['path'])==c['sha256'];assert sha(out/'model.onnx')==summary['onnxSha256'];assert sha(out/'dictionary.json')==summary['dictionarySha256'];assert json.loads((out/'dictionary.json').read_text())==json.loads(Path('/workspace/scratch/ocr-production-development-20261015-v1/models/ascii-dictionary.json').read_text());assert not (out/'metadata.json').exists();assert shutil.disk_usage(PARENT).free>=1024**3;source=Path(__file__).parent
 for name,path in {'official-config.json':ASSETS/'config.json','official-inference.yml':ASSETS/'inference.yml','foundation-model-card.md':ASSETS/'README.md','model-APACHE-2.0.txt':Path('/usr/share/common-licenses/Apache-2.0'),'adapter.py':source/'adapter.py','model.py':source/'model.py','image_tensor.py':source.parent/'image_tensor.py','original-training-protocol.json':source/'protocol.json'}.items():shutil.copyfile(path,out/name)
 receipts=out/'receipts';receipts.mkdir()
 for name,path in {'registration-freeze.json':ROOT/'registration-freeze.json','training-freeze.json':ROOT/'freeze.json','selection.json':ROOT/'selection.json','original-qualification-FAIL.json':RESULTS/'qualification.json','original-fresh-FAIL.json':RESULTS/'fresh-comparison.json','original-final-verification.json':RESULTS/'final-verification.json','onnx-fidelity.json':stage/'summary.json','foundation-download-receipt.json':ASSETS/'download-receipt.json','font-download-receipt.json':PARENT/'assets/font-download-receipt.json','all-font-license-readiness.json':PARENT/'assets/readiness.json'}.items():shutil.copyfile(path,receipts/name)
 licenses=out/'font-licenses';licenses.mkdir()
 for name,path in LICENSES.items():shutil.copyfile(path,licenses/(name+'-LICENSE.txt'))
 contract={'format':'Standard ONNX opset17; FP32 probabilities/reject, full438 dictionary, standard ai.onnx/empty domains only','input':{'x':'FLOAT32[B,3,48,W], BGR, W320..960; B1/2 dynamically verified','valid_width':'INT64[B], true resampled content width1..W'},'output':{'probabilities':'FLOAT32[B,T,438], fullsoftmax; no ASCII renormalization','reject_probability':'FLOAT32[B], uncalibrated sigmoid'},'dictionary':'blank0; pinned official438 character ordering includes finalspace437, dictionary.json exactvalueequal to active model','preprocess':'Externally frame all original nonwhite ink with bbox+2 pixels and retain supplied crop provenance. tensor() in image_tensor.py performs originalpixel center bilinear BGR resize to H48 with uint8round, FP32 normalization and normalized0 padding. Mininputwidth320; aspect ratios requiring W>960 are refused. No target-dependent glyph/baseline/spacing change.','ctc':'Greedy argmax over all438, blank removes, consecutive identicalclass collapses; piece Confidence=max classprobability over run. Source frame intervals kept. End*inputWidth>validWidth*T is unsupportedpadding, refuse rather than clamp. Native source endpoints/offsets map through actual supplied crop; no invented/gold crop correction.','rejectMask':'(2*t+1)*inputWidth < 2*T*validWidth; original pixel center, exact integer arithmetic','diagnosticAcceptance':'Nonempty printableASCII, raw minpieceCTC>=.8, uncalibrated reject<=.05, no unsupportedpadding. Original raw CTC/confidence/source/reject retained; no posterior boost, percasebest, lexicon, lookup or text repair.','qualification':'Original independentfresh code190→185/256,edits75→79; FAIL and factorybaselinefallback remain. Separate exploratory component for consumed actualmanual route comparison only; no default/full-document/iOS qualification.','torchState':'No duplicate SF bundled to save space. Original selected epoch2 strict Adapter state path/SHA in metadata; actual initializer and teacher are font-balanced-v1 epoch4. Foundation architecture/config are official PP-OCRv5 English.'};save(out/'format-contract.json',contract)
 metadata={'status':'EXPLORATORY; original V4 FAIL, inactive/unpublished','originalQualificationSha256':sha(RESULTS/'qualification.json'),'activeBaselineOnnxSha256':'9dd3ed77db4f2af171cf434d200c666033c9bdfe5f33446bc47dbfecac90d703','initializerAndTeacherCheckpointSha256':'7313bee5dabf17998010c6f47844fe80649744b03c0366af05c627fc47314547','selectedByOriginalDevelopmentOnly':c['name'],'checkpointPath':c['path'],'checkpointSha256':c['sha256'],'onnxSha256':summary['onnxSha256'],'dictionarySha256':summary['dictionarySha256'],'foundation':'Official HF PP-OCRv5 English architecture/full438, revision e4abce2bbd335f6c3eda0507b7f8e8abd5af3419; actual state is adapted v1 continuation','licenses':'Foundation Apache2 and font OFL/Apache copies bundled; see pinned receipts','dependencies':{n:importlib.metadata.version(n) for n in ['torch','transformers','onnx','onnxruntime','numpy','Pillow','safetensors','fonttools']},'linuxOrtCpuOnly':True,'nativeWindowsQualified':False,'iosExecutedOrEdited':False,'coremlAttempted':False,'defaultSwitched':False,'publishedByThisAgent':False};save(out/'metadata.json',metadata)
 (out/'README.md').write_text('# Exploratory V4 epoch2 ONNX\n\n**Original trial FAIL; active v1 baseline remains.** Original dev selected this fixed checkpoint before fresh. Independent fresh code accuracy regressed190→185/256 with75→79character edits; the improved false-accept counts do not establish code accuracy gain. This separate export is explicitly requested for consumed actual Windows manual-document route investigation. It does not alter the trial, reselect epochs or re-open fresh.\n\nmodel.onnx is standard FP32 opset17 with full438 dictionary, x plus int64 valid_width. Preserve original pixels, supplied crop provenance, sourceCTC intervals, raw run-max confidence, unsupportedpadding refusal and reject output; see format-contract.json. Actual initializer/teacher are adapted font-balanced-v1 epoch4; pinned official PP-OCRv5 English is the architecture/foundation.\n\nAll624frozen dev rows and12dynamic numerical shapes were checked with Torch2threads/LinuxORT CPU. No iOS/CoreML execution, full-document qualification, automatic adoption or publication is implied. The existing strict SF checkpoint is referenced by hash and is not duplicated.\n',encoding='utf-8',newline='\n')
 files={str(p.relative_to(out)):{'bytes':p.stat().st_size,'sha256':sha(p)} for p in out.rglob('*') if p.is_file()};receipt={'root':str(out),'files':files,'fileCount':len(files),'totalBytes':sum(v['bytes'] for v in files.values()),'originalTrialFailUnchanged':sha(RESULTS/'qualification.json')==summary['originalQualificationSha256'],'sourceSha256':sha(__file__),'allFilesVerified':True,'freeBytes':shutil.disk_usage(PARENT).free,'activated':False};assert receipt['originalTrialFailUnchanged'];assert sum(p.stat().st_size for p in PARENT.rglob('*') if p.is_file())<=1.3*1024**3 and receipt['freeBytes']>=1024**3;save(stage/'package-receipt.json',receipt);print(json.dumps({k:v for k,v in receipt.items() if k!='files'}),flush=True)

